namespace OpenTPW.UI.Original;

/// <summary>
/// The original game's 22 pointers and the pointer each tool mode selects. The pointer ids and their .tga files come from the cursor loader of the
/// Windows executable and the rules from its tool-pointer switch (<see cref="OriginalPointerTables"/>, generated by tpw_exe_layouts.py).
/// </summary>
// [BIN:TPW-EXE:0x489ca0 pointer init] the cursor init loads the .ani set and the .tga set (0x4899c0), hides the system pointer (ShowCursor 0) and starts with pointer 1 (busy)
// [BIN:TPW-EXE:0x52f950 tool pointer] the tool mode (0x81ae2c) picks the pointer; then noplace (8) when 0x527950 is true and cash (20) when 0x816d5c is set override it
// [EXT:software-pointers] the pointer art is drawn by the UI from the colour strips of Data/ui/cursors, a design choice: the host platforms cannot load animated Windows cursors
// [APPROX:UI-100] OpenTPW selects link for completed path/queue previews only (docs/CURSOR-LINK-PREVIEW.md); refused-preview arbitration and the end flag 0x816d4c remain unmodelled. It sets 0x816d5c (cash) for the money refusals of Buy Land, the blueprint and the cell lines only: cash is set when the active tool's cost (0x52fbc0) exceeds the bank balance in the purchase gate 0x5234d0 (0x523662, modelled), at 0x5323c1 (Buy Land, modelled), 0x53593f (the cell validator, modelled through the line preview's money stop) and 0x539fb6 (not modelled); end when the path validator 0x535670 returns code 0xb (0x535ae5, 0x535b3d) and at 0x53a1c6; link by 0x535670 at 0x535c72 and for code 8, a queue end (0x535d00); the crosshair's art (CCro.tga) is not in the game data, so OpenTPW keeps the system pointer there
public static class OriginalPointers
{
	public const int Count = 22;
	public const int Busy = 1, Place = 7, NoPlace = 8, Cash = 20;

	// the OpenTPW pointer type of each original id (the .tga names order the Input enum alphabetically)
	private static readonly Input.CursorTypes[] Types =
	{
		Input.CursorTypes.Normal, Input.CursorTypes.Busy, Input.CursorTypes.Pick, Input.CursorTypes.Path, Input.CursorTypes.Queue, Input.CursorTypes.Line,
		Input.CursorTypes.Track, Input.CursorTypes.Place, Input.CursorTypes.NoGo, Input.CursorTypes.Carry, Input.CursorTypes.Erase, Input.CursorTypes.Pylon,
		Input.CursorTypes.Height, Input.CursorTypes.Rotate, Input.CursorTypes.Pivot, Input.CursorTypes.Sdn, Input.CursorTypes.Sup, Input.CursorTypes.Move,
		Input.CursorTypes.End, Input.CursorTypes.Camcorder, Input.CursorTypes.Cash, Input.CursorTypes.Crosshair,
	};

	/// <summary>The file name (without extension) of pointer <paramref name="id"/> in Data/ui/cursors (the game finds it case-insensitively).</summary>
	public static string File( int id ) => System.IO.Path.GetFileNameWithoutExtension( OriginalPointerTables.Files.Single( entry => entry.Id == id ).File );

	public static Input.CursorTypes TypeOf( int id ) => Types[id];

	/// <summary>The original pointer id of an OpenTPW pointer type.</summary>
	public static int IdOf( Input.CursorTypes type ) => Array.IndexOf( Types, type );

	/// <summary>
	/// The pointer the original shows for <paramref name="toolMode"/> (null: the tool sets none and the previous pointer stays). The link and end
	/// flags override the tool's own pointer in that order, then noplace and cash override whatever was chosen.
	/// </summary>
	public static int? ForTool( int toolMode, bool link = false, bool end = false, bool noPlace = false, bool cash = false )
	{
		int? pointer = null;
		foreach ( var (mode, overrides, fallback) in OriginalPointerTables.ToolRules )
		{
			if ( mode != toolMode )
				continue;
			pointer = fallback;
			foreach ( var (flag, over) in overrides )
			{
				if ( flag == ToolPointerFlag.Link ? link : end )
				{
					pointer = over;
					break;
				}
			}
		}
		if ( noPlace )
			pointer = NoPlace;
		if ( cash )
			pointer = Cash;
		return pointer;
	}
}
